const pptxgen = require('pptxgenjs');

const C = {
  ink: '111827',
  slate: '334155',
  muted: '64748B',
  line: 'CBD5E1',
  panel: 'FFFFFF',
  panel2: 'F8FAFC',
  bg: 'F3F7FA',
  openai: '10A37F',
  google: '4285F4',
  anthropic: 'D97706',
  muse: 'C026D3',
  other: '6B7280',
  warn: 'EF4444',
  gold: 'F59E0B',
  teal: '14B8A6',
  purple: '7C3AED'
};

function addTitle(slide, title, kicker) {
  if (kicker) slide.addText(kicker.toUpperCase(), { x: 0.45, y: 0.25, w: 4.8, h: 0.22, fontFace: 'Arial', fontSize: 7.5, bold: true, color: C.muted, charSpace: 1.2, margin: 0 });
  slide.addText(title, { x: 0.45, y: 0.48, w: 8.7, h: 0.45, fontFace: 'Arial', fontSize: 19, bold: true, color: C.ink, margin: 0, fit: 'shrink' });
  slide.addShape(pptxgen.ShapeType.line, { x: 0.45, y: 1.03, w: 9.1, h: 0, line: { color: C.line, width: 0.8 } });
}

function addPage(slide, n, theme) {
  slide.addShape(pptxgen.ShapeType.ellipse, { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent }, line: { color: theme.accent } });
  slide.addText(String(n), { x: 9.3, y: 5.195, w: 0.4, h: 0.15, fontFace: 'Arial', fontSize: 8, bold: true, color: 'FFFFFF', align: 'center', margin: 0 });
}

function card(slide, x, y, w, h, opts = {}) {
  slide.addShape(pptxgen.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.06, fill: { color: opts.fill || C.panel }, line: { color: opts.line || C.line, width: opts.width || 0.8 } });
}

function labOf(model) {
  if (!model || model === '—') return 'Other';
  const m = model.toLowerCase();
  if (m.includes('gpt') || m === 'o3-2025-04-16' || m.includes('realtime')) return 'OpenAI';
  if (m.includes('gemini')) return 'Google';
  if (m.includes('claude') || m.includes('opus') || m.includes('sonnet')) return 'Anthropic';
  if (m.includes('muse')) return 'Muse Spark';
  return 'Other';
}

function labColor(labOrModel) {
  const lab = ['OpenAI','Google','Anthropic','Muse Spark','Other'].includes(labOrModel) ? labOrModel : labOf(labOrModel);
  return lab === 'OpenAI' ? C.openai : lab === 'Google' ? C.google : lab === 'Anthropic' ? C.anthropic : lab === 'Muse Spark' ? C.muse : C.other;
}

function addLegend(slide, x, y) {
  const labs = [['OpenAI', C.openai], ['Google', C.google], ['Anthropic', C.anthropic], ['Muse Spark', C.muse], ['Other', C.other]];
  labs.forEach((l, i) => {
    slide.addShape(pptxgen.ShapeType.rect, { x: x + i * 1.07, y, w: 0.1, h: 0.1, fill: { color: l[1] }, line: { color: l[1] } });
    slide.addText(l[0], { x: x + 0.14 + i * 1.07, y: y - 0.015, w: 0.9, h: 0.13, fontFace: 'Arial', fontSize: 6.5, color: C.slate, margin: 0 });
  });
}

function addSource(slide, text) {
  slide.addText(text || 'Source: Scale SEAL leaderboards brief; scores include confidence intervals where reported.', { x: 0.45, y: 5.23, w: 8.5, h: 0.16, fontFace: 'Arial', fontSize: 6.2, color: C.muted, margin: 0 });
}

function bar(slide, x, y, w, h, value, max, color, label, score, opts = {}) {
  const bw = max ? (value / max) * w : 0;
  slide.addShape(pptxgen.ShapeType.rect, { x, y, w, h, fill: { color: 'E5E7EB' }, line: { color: 'E5E7EB' } });
  slide.addShape(pptxgen.ShapeType.rect, { x, y, w: bw, h, fill: { color }, line: { color } });
  if (label) slide.addText(label, { x: opts.labelX || x, y: y - 0.18, w: opts.labelW || w, h: 0.13, fontFace: 'Arial', fontSize: opts.fontSize || 6.5, color: C.slate, margin: 0, fit: 'shrink' });
  if (score !== undefined) slide.addText(score, { x: x + w + 0.05, y: y - 0.01, w: 0.55, h: 0.12, fontFace: 'Arial', fontSize: opts.scoreSize || 6.8, bold: true, color: C.ink, margin: 0 });
}

function smallPill(slide, text, x, y, color) {
  slide.addShape(pptxgen.ShapeType.roundRect, { x, y, w: 0.76, h: 0.18, rectRadius: 0.08, fill: { color }, line: { color } });
  slide.addText(text, { x, y: y + 0.038, w: 0.76, h: 0.08, fontFace: 'Arial', fontSize: 5.8, bold: true, color: 'FFFFFF', align: 'center', margin: 0 });
}

module.exports = { C, addTitle, addPage, card, labOf, labColor, addLegend, addSource, bar, smallPill };
EOF

